const PUBLICATION_SKY_DATE = "2026-08-20";

function cleanTicker(value:string){return value.trim().toUpperCase().replace(/\.(NS|BO)$/i,"").replace(/[^A-Z0-9&-]/g,"")}
function currentSkyDate(){const parts=new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Kolkata",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date());const value=(kind:string)=>parts.find(part=>part.type===kind)?.value||"";return `${value("year")}-${value("month")}-${value("day")}`}
function skyDateLabel(value?:string){if(!value)return "Current IST sky";return new Date(`${value}T12:00:00`).toLocaleDateString("en-GB",{timeZone:"Asia/Kolkata",day:"numeric",month:"short",year:"numeric"})}
function labelFromTicker(ticker:string){return ticker.replace(/&/g," & ").replace(/-/g," ")}
function rangeLabel(windowValue?:EngineEvent|null){if(!windowValue)return "No separate window mapped";const label=windowValue.label||windowValue.state||windowValue.phase||"Mapped window";const dates=[windowValue.start,windowValue.end].filter(Boolean).join("–");return dates?`${label} · ${dates}`:label}
function toneFromState(state:string,direction:string):Tone{const text=`${state} ${direction}`.toUpperCase();if(text.includes("BREAK"))return "break";if(text.includes("PRESSURE")&&text.includes("FORM"))return "forming-pressure";if(text.includes("PRESSURE"))return "pressure";if(text.includes("DURABLE"))return "durable";if(text.includes("EXPANSION")||text.includes("RERATING"))return "expansion";return "contested"}
function adaptEngineReading(payload:EnginePayload):Stock|null{
  const raw=payload?.row;const model=raw?.astro_model;if(!raw||!model?.current||!model?.scores)return null;
  const currentState=model.current.state||"Current astro state";
  const ticker=cleanTicker(raw.name||raw.symbol||payload.symbol||"");if(!ticker)return null;
  const tactical=(model.paths?.tactical||[]).slice(0,3).map((event:EngineEvent)=>rangeLabel(event));
  const strategic=(model.paths?.strategic||[]);const pressureWindow=model.windows?.pressure||model.windows?.breakRisk;
  const renewalEvent=strategic.find((event:EngineEvent)=>/EXPANSION|RERATING|SUPPORT|RECOVER/i.test(String(event?.label||event?.state||"")));
  const episodes=Array.isArray(model.cycle?.episodes)?model.cycle.episodes.length:0;
  const chartType=raw.natal_chart_type||model.natal?.chartType||model.natal?.chartAuthority||"approved";
  const confidence=Number(payload.chartConfidence??model.natal?.reliability??raw.natal_reliability??50);
  return {ticker,name:raw.company_name||model.natal?.companyName||labelFromTicker(ticker),reading:currentState,tone:toneFromState(currentState,model.current.direction||""),e:Number(model.scores.expansion||0),p:Number(model.scores.pressure||0),phase:[model.current.expansionStage,model.current.pressureStage].filter(Boolean).join(" · ")||currentState,window:rangeLabel(model.windows?.rerating||model.windows?.pressure),nearPath:tactical.length?tactical:[currentState],nextInflection:tactical[1]||"No separate turning point mapped",pressure:rangeLabel(pressureWindow),potential:`${model.cycle?.level||"Measured"} long-cycle structure`,score:Number(model.cycle?.score??model.scores.cycleRunway??0),episodes,forward:Number(model.scores.forwardLeadership||0),interruption:rangeLabel(model.windows?.breakRisk||model.windows?.pressure),renewal:renewalEvent?rangeLabel(renewalEvent):"No separate renewal mapped",chart:payload.chartBasisLabel||`Verified ${String(chartType).toLowerCase()} chart`,confidence,story:model.current.story||"The Astro engine returned an approved current reading.",skyDate:payload.skyDate,engineVersion:payload.engineVersion||model.version||"v37.9.14",natalFingerprint:payload.natalFingerprint,cacheState:"fresh"};
}
async function fetchApprovedReading(value:string){const ticker=cleanTicker(value);const response=await fetch(`/api/get-stocks?symbols=${encodeURIComponent(`${ticker}.NS`)}`,{headers:{accept:"application/json"}});const rows=await response.json() as Array<EnginePayload["row"]>;const row=Array.isArray(rows)?rows[0]:undefined;const payload={success:Boolean(row),status:row?"verified-engine-reading":"natal-unavailable",symbol:`${ticker}.NS`,skyDate:(row as {as_of_date?:string;sky_date?:string}|undefined)?.as_of_date||(row as {sky_date?:string}|undefined)?.sky_date||currentSkyDate(),engineVersion:(row?.astro_model?.version)||"v37.9.14",natalFingerprint:(row as {natal_chart_id?:string}|undefined)?.natal_chart_id||ticker,row,error:row?undefined:"This company is not in the approved natal registry."};return {response:{ok:response.ok&&Boolean(row)},payload:payload as EnginePayload&{status?:string;reason?:string;error?:string}}}
async function fetchHistoricalReplay(ticker:string,date:string){const response=await fetch(`/api/replay-lab?ticker=${encodeURIComponent(`${cleanTicker(ticker)}.NS`)}&date=${encodeURIComponent(date)}&forwardDays=730&raw=1`,{headers:{accept:"application/json"}});const payload=await response.json() as ReplayPayload;return {response,payload}}
async function requestCompanyAdmission(value:string):Promise<AddResult>{return {status:"natal-unavailable",message:`${cleanTicker(value)} is not yet in the approved natal registry. Add its verified natal record to the engine before publishing a subscriber reading.`}}

