function ReplaySection({stocks}:{stocks:Stock[]}){
  const [mode,setMode]=useState<"sky"|"archive">("sky"); const [date,setDate]=useState("2025-08-15"); const [ticker,setTicker]=useState(stocks[0]?.ticker||""); const [payload,setPayload]=useState<ReplayPayload|null>(null);const [archiveStock,setArchiveStock]=useState<Stock|null>(null);const [loading,setLoading]=useState(false);const [error,setError]=useState("");const today=currentSkyDate();
  useEffect(()=>{const timer=window.setTimeout(()=>{const requested=new URLSearchParams(window.location.search).get("replayStock")?.replace(".NS","").toUpperCase();if(requested&&stocks.some(s=>s.ticker===requested))setTicker(requested)},0);return()=>window.clearTimeout(timer)},[stocks]);
  const company=stocks.find(s=>s.ticker===ticker);
  const clear=()=>{setPayload(null);setArchiveStock(null);setError("")};
  const run=async()=>{clear();if(!ticker||!date)return;setLoading(true);try{if(mode==="archive"){if(date!==PUBLICATION_SKY_DATE||!company)throw new Error("No sealed publication was stored for this company on that date. The private beta archive currently contains the 20 Aug 2026 publication batch.");setArchiveStock(company);return}const result=await fetchHistoricalReplay(ticker,date);if(!result.response.ok||!result.payload.success)throw new Error(result.payload.error||"The historical sky could not be calculated.");setPayload(result.payload)}catch(reason){setError(reason instanceof Error?reason.message:"The historical sky could not be calculated.")}finally{setLoading(false)}};
  return <section className="replay" id="replay"><div className="replay-copy"><span className="eyebrow">Historical research</span><h2>Replay Lab</h2><p>Run v37.9.14 under a past sky—or retrieve an immutable reading from a stored publication batch.</p><ul><li>Historical transits are calculated for the selected date.</li><li>Present-day data cannot rewrite the result.</li><li>Price is not used by the astrology engine.</li></ul></div><div className="replay-panel"><div className="replay-tabs"><button className={mode==="sky"?"active":""} onClick={()=>{setMode("sky");clear()}}>Historical Sky Replay</button><button className={mode==="archive"?"active":""} onClick={()=>{setMode("archive");setDate(PUBLICATION_SKY_DATE);clear()}}>Published Archive</button></div><p>{mode==="sky"?"Recalculate v37.9.14 using only the selected historical sky and the approved natal chart. Replays are not limited by the dashboard.":"Open the exact cached reading from an available publication date."}</p><div className="replay-controls"><label><span>COMPANY</span><select value={ticker} onChange={e=>{setTicker(e.target.value);clear()}}>{stocks.map(s=><option value={s.ticker} key={s.ticker}>{s.name}</option>)}</select></label><label><span>{mode==="sky"?"REPLAY DATE":"PUBLICATION DATE"}</span><input type="date" value={date} min="1990-01-01" max={mode==="sky"?today:PUBLICATION_SKY_DATE} onChange={e=>{setDate(e.target.value);clear()}}/></label><button onClick={()=>void run()} disabled={loading||!ticker||!date}>{loading?"Calculating historical sky…":`View ${mode==="sky"?"historical sky":"published reading"}`}</button></div>{error&&<div className="replay-error"><b>Replay unavailable</b><p>{error}</p></div>}{archiveStock&&<div className="replay-output"><div className="replay-result"><span className="live-dot"/><div><b>{archiveStock.name} · Published Archive · 20 Aug 2026</b><small>Exact private-beta publication reading. It is retrieved rather than recalculated.</small></div><button onClick={clear}>Close result</button></div><StockReading s={archiveStock}/></div>}{payload&&<div className="replay-output"><div className="replay-result"><span className="live-dot"/><div><b>{company?.name} · Historical Sky Replay · {new Date(`${date}T12:00:00`).toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"numeric"})}</b><small>Calculated by v37.9.14 from the selected historical sky. No present-day market information was used.</small></div><button onClick={clear}>Return to controls</button></div><ResearchEvidence payload={payload}/></div>}</div></section>
}

function ReadingGuide(){
  const phases=[
    ["Expansion","Supportive astrological conditions have more authority than pressure. This can improve momentum, participation or opportunity, but it does not promise a price rise."],
    ["Rerating","Expansion has become persistent or repeated enough to support a more meaningful change in how the stock expresses leadership. It is an astrological structure—not a valuation or return forecast."],
    ["Rerating strengthening","The rerating structure is gaining authority but has not yet reached its most established phase."],
    ["Rerating established","The rerating structure is active and mature enough to govern the current reading, subject to any stated pressure or interruption."],
    ["Compressed rerating","The rerating structure remains intact, but pressure is restricting its expression. Progress may be slower, selective or interrupted rather than absent."],
    ["Volatile expansion","Support remains stronger than pressure, but volatile contacts can produce an uneven path, rapid reversals or exaggerated reactions."],
    ["Volatile rerating","A meaningful rerating structure is active, but volatility can disrupt how cleanly it expresses. The supportive structure and the unstable path are both real."],
    ["Pressure","Restraining conditions have authority. They can delay, compress or distort expression; pressure does not automatically mean that every stock must fall."],
    ["Pressure forming","A pressure pattern is developing but has not yet taken control. It is an early-warning state, not the same as active pressure."],
    ["Peak pressure","The pressure sequence is near its strongest measured phase. Relief afterward is possible, but recovery requires a later supportive structure."],
    ["Durable expansion","Support repeats across the measured runway and remains resilient through ordinary pressure. It describes structural persistence, not guaranteed performance."],
    ["Break-Risk","A specifically qualified destructive structural-pressure network. It is more serious than ordinary pressure and is never inferred merely from a long quiet period."]
  ];
  const terms=[
    ["E / P","Expansion and Pressure intensity, each measured independently out of 100."],
    ["Current reading","The governing astrological condition on the selected sky date."],
    ["Phase maturity","Whether a condition is forming, strengthening, established, mature or exhausting."],
    ["Active window","The date range during which the current governing condition remains authoritative."],
    ["Near-term path","Up to three meaningful changes across the next 45 days; minor events are excluded."],
    ["24-month astro potential","The measured runway for repeated expansion, leadership durability and survival through pressure."],
    ["Principal risk","The strongest interruption that could override or delay the otherwise supportive structure."],
    ["Chart confidence","Reliability of the approved natal basis—not confidence that a market outcome must occur."],
    ["Turning point (inflection)","A direction-neutral transition field: an existing trend may accelerate, stall, reverse or rotate. Each stock’s natal contacts determine whether it expresses as support or pressure."],
    ["Watch","A turning-point or volatility field whose direction is not predetermined and depends on each stock’s natal response."]
  ];
  return <details className="reading-guide" id="reading-guide"><summary><span><b>Reading guide</b><small>Plain-English phase definitions, colour meanings and methodology notes</small></span><i>＋</i></summary><div className="guide-colours"><span className="macro-tag neutral">neutral</span><p>Balanced or no dominant force</p><span className="macro-tag expansion">expansion</span><p>Supportive or rerating-oriented</p><span className="macro-tag pressure">pressure</span><p>Compression, restraint or structural stress</p><span className="macro-tag watch">watch</span><p>Turning point or volatility; direction is not predetermined</p></div><section className="guide-section"><div className="guide-heading"><span className="eyebrow">How to read the phases</span><h3>What Fin-Lumen’s recurring terms mean</h3><p>Each phrase describes the balance and maturity of astrological structure. It does not predict a financial return.</p></div><div className="phase-grid">{phases.map(([term,meaning])=><div key={term}><b>{term}</b><p>{meaning}</p></div>)}</div></section><section className="guide-section guide-reference"><div className="guide-heading"><span className="eyebrow">Table reference</span><h3>Scores, windows and confidence</h3></div><div className="term-grid">{terms.map(([term,meaning])=><div key={term}><b>{term}</b><p>{meaning}</p></div>)}</div></section></details>
}

function AddStockModal({stocks,watchlist,onRequestAdd,onClose}:{stocks:Stock[];watchlist:string[];onRequestAdd:(value:string)=>Promise<AddResult>;onClose:()=>void}){
  const [query,setQuery]=useState("");const [checked,setChecked]=useState(false);const [loading,setLoading]=useState(false);const [result,setResult]=useState<AddResult|null>(null);
  const normalized=cleanTicker(query);const known=stocks.find(s=>s.ticker===normalized||s.name.toUpperCase()===query.trim().toUpperCase());
  const check=async()=>{setChecked(true);setResult(null);if(known)return;setLoading(true);try{setResult(await onRequestAdd(query))}catch(error){setResult({status:"error",message:error instanceof Error?error.message:"The company could not be added."})}finally{setLoading(false)}};
  const addKnown=async()=>{if(!known)return;setLoading(true);try{setResult(await onRequestAdd(known.ticker))}catch(error){setResult({status:"error",message:error instanceof Error?error.message:"The company could not be added."})}finally{setLoading(false)}};
  const reset=(value:string)=>{setQuery(value);setChecked(false);setResult(null)};
  return <div className="drawer-backdrop modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="add-modal" role="dialog" aria-modal="true" aria-label="Add a stock"><button className="close" onClick={onClose}>×</button><span className="eyebrow">Add to My Stocks · {watchlist.length}/100</span><h2>Enter a company or ticker.</h2><p>One check searches approved readings first. If none exists, Fin-Lumen automatically pulls the official exchange record and prepares its natal candidate for verification.</p><div className="add-search"><input autoFocus value={query} onChange={e=>reset(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")void check()}} placeholder="For example: IRFC.NS or MARUTI.NS"/><button onClick={()=>void check()} disabled={!query.trim()||loading||watchlist.length>=100}>{loading?"Checking…":"Find company"}</button></div>{loading&&<p className="checking-note">Searching approved readings and official exchange evidence. A new company may take a few seconds.</p>}{!checked&&<div className="suggestions"><span>{ENGINE_SUPPORTED_SYMBOLS.length} engine-supported symbols · try:</span>{["MARUTI","ABB","HINDUNILVR","COCHINSHIP"].map(x=><button key={x} onClick={()=>reset(x)}>{x}</button>)}</div>}
      {checked&&known&&<div className="availability available"><span>✓</span><div><b>Approved reading available</b><p>{watchlist.includes(known.ticker)?`${known.name} is already in My Stocks.`:`${known.name} can be restored immediately from its cached reading.`}</p><small>{known.chart} · {known.confidence}/100 reliability{known.cacheState==="browser"?" · browser cache":""}</small></div><button disabled={watchlist.includes(known.ticker)||loading} onClick={()=>void addKnown()}>{watchlist.includes(known.ticker)?"Already added":loading?"Adding…":"Add company"}</button></div>}
      {result?.status==="added"&&!known&&<div className="availability available"><span>✓</span><div><b>Added to My Stocks</b><p>{result.message}</p><small>Its approved reading is now available without recalculating the rest of the table.</small></div><button onClick={onClose}>View table</button></div>}
      {result&&["preparing-evidence","candidate-ready","owner-review"].includes(result.status)&&<div className={`availability ${result.status==="owner-review"?"reviewing":"preparing"}`}><span>{result.status==="owner-review"?"◇":result.status==="candidate-ready"?"✓":"◷"}</span><div><b>{result.status==="owner-review"?"Owner verification required":result.status==="candidate-ready"?"Official listing candidate prepared":"Company request recorded"}</b><p>{result.message}</p><small>No reading will appear until official evidence is checked and a natal basis is approved.</small></div><button onClick={onClose}>Done</button></div>}
      {result&&!["added","preparing-evidence","candidate-ready","owner-review"].includes(result.status)&&<div className={`availability ${result.status==="engine-unreachable"||result.status==="error"?"preparing":"unavailable"}`}><span>{result.status==="engine-unreachable"?"↻":"○"}</span><div><b>{result.status==="engine-unreachable"?"Astro engine temporarily unavailable":result.status==="identity-needed"?"Exact ticker needed":"Official company record not found"}</b><p>{result.message}</p><small>{result.status==="identity-needed"?"Use an exchange ticker so the legal company is not guessed.":"Nothing has been added to the approved universe."}</small></div><button onClick={()=>{setChecked(false);setResult(null)}}>{result.status==="identity-needed"?"Enter ticker":"Try again"}</button></div>}
      {watchlist.length>=100&&<p className="capacity-note">Your personal table has reached its 100-company limit. Remove one company before adding another.</p>}
    </section></div>
}

function AdmissionQueue(){
  const [requests,setRequests]=useState<AdmissionRequest[]>([]);const [loading,setLoading]=useState(false);const [loaded,setLoaded]=useState(false);
  const load=async()=>{if(loaded||loading)return;setLoading(true);try{const response=await fetch("/api/company-admissions",{headers:{accept:"application/json"}});const payload=await response.json() as {requests?:AdmissionRequest[]};setRequests(payload.requests||[]);setLoaded(true)}catch{}finally{setLoading(false)}};
  return <details className="admission-queue" onToggle={event=>{if(event.currentTarget.open)void load()}}><summary><span><span className="eyebrow">Universe development</span><b>New company admission queue</b><small>Requested companies remain outside published readings until their natal basis is approved.</small></span><i>＋</i></summary><div className="admission-body">{loading&&<p>Loading company requests…</p>}{loaded&&requests.length===0&&<p>No new companies are awaiting verification.</p>}{requests.map(request=><article key={request.id}><div><b>{request.companyName}</b><small>{request.symbol} · {request.exchange} · requested {request.requestCount} time{request.requestCount===1?"":"s"}{request.isin?` · ${request.isin}`:""}</small></div><span className={`admission-status ${request.status}`}>{request.status==="owner-review"?"Owner review":request.status==="candidate-ready"?"Candidate ready":request.status==="needs-evidence"?"Needs evidence":"Evidence preparation"}</span><p>{request.evidenceStage}{request.listingDate?` · Listing ${request.listingDate}`:""}</p></article>)}</div></details>
}
